    refTB2: "Wahyu 22:2",
    version: "NKJV",
    text: "In the middle of its street, and on either side of the river, was the tree of life, which bore twelve fruits, each tree yielding its fruit every month. The leaves of the tree were for the healing of the nations.",
    tb2: "Di tengah-tengah jalan kota itu, yaitu di seberang-menyeberang sungai itu, ada pohon-pohon kehidupan yang berbuah dua belas kali, tiap-tiap bulan sekali; dan daun pohon-pohon itu dipakai untuk menyembuhkan bangsa-bangsa."
