    tb2: "Roh dan pengantin perempuan itu berkata: \"Marilah!\" Dan barangsiapa yang mendengarnya, hendaklah ia berkata: \"Marilah!\" Dan barangsiapa yang haus, hendaklah ia datang, dan barangsiapa yang mau, hendaklah ia mengambil air kehidupan dengan cuma-cuma!"
